<!-- Native form island; application controllers own drafts and staged imports. -->
<template>
<dialog id="settingsDialog" class="dialog settings-dialog" aria-labelledby="settingsTitle"><div class="modal-toast-wrap"><div class="toast" data-toast-host role="status" aria-live="polite" aria-atomic="true" hidden></div></div><form id="settingsForm" novalidate><div class="dialog-heading"><h2 id="settingsTitle">附加设置</h2><button type="button" class="icon-btn" data-close aria-label="关闭设置"><span class="icon material-icon" aria-hidden="true">close</span></button></div><nav class="settings-tabs" aria-label="附加规则分类"><button type="button" data-settings-tab="general">朗读设置</button><button type="button" data-settings-tab="normal">普通</button><button type="button" data-settings-tab="direction">连坐</button><button type="button" data-settings-tab="time">时间</button><button type="button" data-settings-tab="friend">友尽</button></nav><div class="dialog-body"><section data-settings-panel="normal"><h3>公平与冷却</h3><label>近期冷却轮数<input id="cooldownInput" type="number" min="1" max="20" required><span class="field-hint">人数不足时自动缩小，至少避免连续抽中。</span></label><label>均衡强度 <span id="strengthValue" class="value-label">1.6</span><input id="strengthInput" type="range" min="0.5" max="3" step="0.1"><span class="field-hint">累计少抽、常晚抽的同学增权；长期反馈保留。</span></label></section><section data-settings-panel="direction" hidden><h3>连坐规则</h3><div class="direction-range"><span>连坐持续轮数</span><div class="form-grid"><label>最少轮数<input id="directionMinInput" type="number" min="1" max="50" required></label><label>最多轮数<input id="directionMaxInput" type="number" min="1" max="50" required></label></div><span class="field-hint">包含触发轮；相同数值为固定轮数，遇到边界或公平保护提前退出。</span></div><div class="direction-range direction-cooldown-range"><span>连坐结束后的冷却</span><div class="form-grid"><label>最少冷却轮数<input id="directionCooldownMinInput" type="number" min="0" max="50" step="1" required></label><label>最多冷却轮数<input id="directionCooldownMaxInput" type="number" min="0" max="50" step="1" required></label></div><span id="directionCooldownHint" class="field-hint"></span></div><label>接力方向<select id="directionInput"><option value="auto">每轮随机选择可用方向</option><option value="up">向上（靠近讲台）</option><option value="right">向右</option><option value="down">向下（远离讲台）</option><option value="left">向左</option></select></label></section><section data-settings-panel="time" hidden><h3>日期／时间学号规则</h3><div class="form-grid"><label>数字来源<select id="timeSourceInput"><option value="time">时间 HHmmss（6 位）</option><option value="date">日期 YYYYMMDD（8 位）</option><option value="datetime">日期＋时间（14 位）</option></select></label><label>选取位置（从 1 开始）<input id="positionsInput" placeholder="例如 5,6" required maxlength="60"></label></div><label>取位方式<select id="timeSelectionInput"><option value="random">随机选取连续两位</option><option value="fixed">指定取位</option></select></label><div class="digit-preview"><p>点击数字调整取位顺序</p><div id="digitButtons" class="digit-buttons"></div><span id="digitResult"></span></div></section><section data-settings-panel="friend" hidden><h3>友尽目标</h3><p id="friendDetailSummary" class="field-hint"></p><p class="field-hint">上一位有可抽目标时独立判定，不参与三种普通方式的百分比合计。目标仍遵守冷却、未抽优先和长期公平保护。</p><button type="button" id="friendManageTargetsBtn" class="btn btn-plain"><span class="icon material-icon" aria-hidden="true">groups</span>在座位表设置目标<span class="icon material-icon" aria-hidden="true">arrow_forward</span></button></section><section data-settings-panel="general" hidden><h3>朗读设置</h3><label class="checkbox-label"><input id="voiceInput" type="checkbox" class="rect-switch" role="switch">抽中后朗读姓名</label><div id="speechProviderMount"></div></section><p id="settingsError" class="error-message" role="alert"></p></div><div class="dialog-footer"><button type="button" class="btn btn-plain" data-close>取消</button><button type="submit" class="btn btn-primary">保存规则<span class="icon material-icon" aria-hidden="true">check</span></button></div></form></dialog><dialog id="importDialog" class="dialog import-dialog" aria-labelledby="importTitle"><div class="modal-toast-wrap"><div class="toast" data-toast-host role="status" aria-live="polite" aria-atomic="true" hidden></div></div><div class="dialog-heading"><div><span class="eyebrow">每一个名字，都值得被记住</span><h2 id="importTitle">导入名单</h2></div><button class="icon-btn" data-close aria-label="关闭导入"><span class="icon material-icon" aria-hidden="true">close</span></button></div><div class="dialog-body"><div id="providerSettingsMount"></div><div id="importEntry"><div class="segmented import-tabs" role="group" aria-label="导入方式"><button data-import-tab="text" class="selected" aria-pressed="true"><span class="icon material-icon" aria-hidden="true">list</span>按行导入</button><button data-import-tab="image" aria-pressed="false"><span class="icon material-icon" aria-hidden="true">image</span>图表识别</button><button data-import-tab="json" aria-pressed="false"><span class="icon material-icon" aria-hidden="true">check</span>识别结果</button></div><div data-import-panel="text"><div class="form-grid import-meta"><label>班级名称<input id="importClassInput" maxlength="40" placeholder="例如：七年级二班"></label><label>每行座位数<input id="importColsInput" type="number" min="1" max="20" value="8"></label></div><label>一行一位同学<textarea id="rosterText" rows="9" placeholder="张三&#10;李四&#10;王五&#10;&#10;也支持：&#10;1,张三&#10;2,李四&#10;&#10;自定义座位：1,张三,1,1" spellcheck="false"></textarea></label><div class="import-text-actions"><label class="btn btn-plain file-label"><span class="icon material-icon" aria-hidden="true">upload</span>选择 TXT / CSV<input id="rosterFile" type="file" accept=".txt,.csv,text/plain,text/csv" class="sr-only"></label><span class="field-hint">支持姓名、学号以及行列坐标</span></div></div><div data-import-panel="image" hidden><div class="vision-grid"><div><label id="imageDrop" class="image-drop" tabindex="0"><input id="imageFile" type="file" accept="image/png,image/jpeg,image/webp" class="sr-only"><span class="icon material-icon" aria-hidden="true">image</span><strong>点击或拖入座位表</strong><span>PNG、JPG、WebP · 最大 8 MB</span><img id="imagePreview" alt="待识别的座位表" hidden></label><p id="imageFileLabel" class="field-hint"></p><button id="clearImageBtn" type="button" class="text-btn" hidden><span class="icon material-icon" aria-hidden="true">close</span>移除座位图</button><button id="copyPromptBtn" class="btn btn-plain full-width"><span class="icon material-icon" aria-hidden="true">auto_awesome</span>复制座位表识别提示词</button><p class="field-hint">可把提示词与图片交给你使用的视觉模型，再切换到「识别结果」粘贴 JSON。</p><textarea id="promptFallback" class="prompt-fallback" readonly hidden aria-label="座位表识别提示词"></textarea></div><div class="vision-config"><h3>识别座位表</h3><p id="visionProviderSummary" class="field-hint"></p><p class="field-hint">可单独加入参考表提取名单，也可同时加入座位图。所选资料发送到提供商，核对后再导入。</p><button id="recognizeBtn" class="btn btn-dark full-width"><span class="icon material-icon" aria-hidden="true">auto_awesome</span>识别所选资料</button><button id="cancelRecognitionBtn" class="btn btn-plain full-width" hidden><span class="icon material-icon" aria-hidden="true">close</span>取消识别</button><p id="recognitionStatus" class="field-hint" role="status"></p></div></div></div><div data-import-panel="json" hidden><p class="inline-hint">粘贴视觉模型输出的 JSON。有座位表时提供 name、row、col；学号不确定时省略 id。纯名单只需姓名和学号，程序会匹配已有座位或询问教室尺寸。</p><label>识别结果<textarea id="visionJson" rows="11" placeholder='{"cols": 4, "students": [{"id": 1, "name": "张三", "row": 1, "col": 1}], "uncertain": []}' spellcheck="false"></textarea></label></div></div><div id="importPreviewSection" hidden><div class="preview-heading"><div><h3>核对名单与座位</h3><p id="importPreviewSummary" class="muted"></p></div><button id="importBackBtn" class="text-btn"><span class="icon material-icon" aria-hidden="true">arrow_back</span>返回修改</button></div><div id="importWarnings" class="warning-box" hidden></div><div class="table-scroll preview-table"><table><thead><tr><th>学号</th><th>姓名</th><th>行</th><th>列</th></tr></thead><tbody id="importPreviewTable"></tbody></table></div><label class="checkbox-label"><input id="importResetInput" type="checkbox" class="rect-switch" role="switch">建立新名单，清空现有抽取进度和长期公平统计</label><p class="field-hint">维护当前班级名单时请关闭此项；已确认匹配的同学会保留累计统计。</p></div><p id="importError" class="error-message" role="alert"></p></div><div class="dialog-footer"><div><button id="previewImportBtn" class="btn btn-primary">预览名单<span class="icon material-icon" aria-hidden="true">arrow_forward</span></button><button id="applyImportBtn" class="btn btn-primary" hidden>确认导入<span class="icon material-icon" aria-hidden="true">check</span></button></div></div></dialog>
<dialog id="studentDialog" class="dialog small-dialog" aria-labelledby="studentTitle"><div class="modal-toast-wrap"><div class="toast" data-toast-host role="status" aria-live="polite" aria-atomic="true" hidden></div></div><form id="studentForm"><div class="dialog-heading"><h2 id="studentTitle">编辑同学</h2><button type="button" class="icon-btn" data-close aria-label="关闭编辑"><span class="icon material-icon" aria-hidden="true">close</span></button></div><div class="dialog-body"><div class="form-grid"><label>学号<input id="studentIdInput" inputmode="numeric" required maxlength="12"></label><label>姓名<input id="studentNameInput" required maxlength="64"></label><label>行<input id="studentRowInput" type="number" min="1" max="50" required></label><label>列<input id="studentColInput" type="number" min="1" max="20" required></label></div><label class="checkbox-label"><input id="studentActiveInput" type="checkbox" class="rect-switch" role="switch">参与抽取</label><p class="field-hint">暂停参与后，该同学不会被抽中，已有统计会保留。</p><p id="studentError" class="error-message" role="alert"></p></div><div class="dialog-footer"><button type="button" class="btn btn-plain" data-close>取消</button><button type="submit" class="btn btn-primary">保存修改</button></div></form></dialog>
<dialog id="confirmDialog" class="dialog small-dialog" aria-labelledby="confirmTitle"><div class="modal-toast-wrap"><div class="toast" data-toast-host role="status" aria-live="polite" aria-atomic="true" hidden></div></div><div class="dialog-heading"><h2 id="confirmTitle"></h2><button class="icon-btn" data-close aria-label="关闭确认"><span class="icon material-icon" aria-hidden="true">close</span></button></div><div class="dialog-body"><p id="confirmText"></p></div><div class="dialog-footer"><button class="btn btn-plain" data-close>取消</button><button id="confirmActionBtn" class="btn btn-primary">确认</button></div></dialog>
<dialog id="classDialog" class="dialog small-dialog" aria-labelledby="classTitle"><div class="modal-toast-wrap"><div class="toast" data-toast-host role="status" aria-live="polite" aria-atomic="true" hidden></div></div><form id="classForm"><div class="dialog-heading"><h2 id="classTitle">班级名称</h2><button type="button" class="icon-btn" data-close aria-label="关闭班级设置"><span class="icon material-icon" aria-hidden="true">close</span></button></div><div class="dialog-body"><label>班级名称<input id="classNameInput" maxlength="40" required></label></div><div class="dialog-footer"><button type="submit" class="btn btn-primary">保存</button></div></form></dialog>
<dialog id="reflowDialog" class="dialog small-dialog" aria-labelledby="reflowTitle"><div class="modal-toast-wrap"><div class="toast" data-toast-host role="status" aria-live="polite" aria-atomic="true" hidden></div></div><form id="reflowForm"><div class="dialog-heading"><h2 id="reflowTitle">重新排座</h2><button type="button" class="icon-btn" data-close aria-label="关闭排座"><span class="icon material-icon" aria-hidden="true">close</span></button></div><div class="dialog-body"><label>每行座位数<input id="reflowColsInput" type="number" min="1" max="20" required></label><p class="field-hint">按当前名单顺序从左到右、从前到后排列。原座位坐标与空座布局会被替换，已有抽取次数保留。</p></div><div class="dialog-footer"><button type="submit" class="btn btn-primary">按名单重新排座</button></div></form></dialog>


<dialog id="importLayoutDialog" class="dialog small-dialog" aria-labelledby="importLayoutTitle"><div class="modal-toast-wrap"><div class="toast" data-toast-host role="status" aria-live="polite" aria-atomic="true" hidden></div></div><form id="importLayoutForm"><div class="dialog-heading"><h2 id="importLayoutTitle">确认教室座位尺寸</h2><button type="button" class="icon-btn" data-close aria-label="取消设置座位尺寸"><span class="icon material-icon" aria-hidden="true">close</span></button></div><div class="dialog-body"><p id="importLayoutSummary" class="field-hint"></p><div class="form-grid"><label>行数<input id="importLayoutRows" type="number" min="1" max="50" step="1" required placeholder="例如 6"></label><label>列数<input id="importLayoutCols" type="number" min="1" max="20" step="1" required placeholder="例如 8"></label></div><p class="field-hint">从最靠近讲台的左侧开始，按学号升序逐行安排。空余座位保留，容量需覆盖全部同学。</p><p id="importLayoutError" class="error-message" role="alert"></p></div><div class="dialog-footer"><button type="button" class="btn btn-plain" data-close>取消</button><button type="submit" class="btn btn-primary">生成座位预览<span class="icon material-icon" aria-hidden="true">check</span></button></div></form></dialog>
</template>
